import{_ as n,o as r,c as i,ah as t}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse('{"title":"Recherche: Die ÖVP-Spendenliste (Heidi Goëss-Horten)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/oevp-spendenliste-details.md","filePath":"recherche/oevp-spendenliste-details.md"}'),s={name:"recherche/oevp-spendenliste-details.md"};function a(o,e,d,l,h,u){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="recherche-die-ovp-spendenliste-heidi-goess-horten" tabindex="-1">Recherche: Die ÖVP-Spendenliste (Heidi Goëss-Horten) <a class="header-anchor" href="#recherche-die-ovp-spendenliste-heidi-goess-horten" aria-label="Permalink to &quot;Recherche: Die ÖVP-Spendenliste (Heidi Goëss-Horten)&quot;">​</a></h1><p><strong>„Pointillismus des Kapitals“ – Wie 931.000 Euro für den Rechnungshof unsichtbar wurden.</strong></p><p>Eines der zentralen Motive in Teil 4 unserer Mockumentary ist der „Regen aus Gold“ – die massiven Parteispenden von Heidi Goëss-Horten an die ÖVP in den Jahren 2018 und 2019. Was oberflächlich wie bürgerliches Engagement aussieht, entpuppt sich bei näherer Betrachtung als ein Meisterwerk der bürokratischen Verschleierung, auch bekannt als „Spendenstückelung“.</p><hr><h2 id="die-nackten-zahlen" tabindex="-1">Die nackten Zahlen <a class="header-anchor" href="#die-nackten-zahlen" aria-label="Permalink to &quot;Die nackten Zahlen&quot;">​</a></h2><p>Heidi Horten war in den Jahren vor der Verschärfung des Parteiengesetzes die mit Abstand größte Einzelspenderin der ÖVP-Bundespartei.</p><h3 id="_1-gesamtvolumen-2018–2019" tabindex="-1">1. Gesamtvolumen (2018–2019) <a class="header-anchor" href="#_1-gesamtvolumen-2018–2019" aria-label="Permalink to &quot;1. Gesamtvolumen (2018–2019)&quot;">​</a></h3><p>Insgesamt flossen <strong>931.000 Euro</strong> von Heidi Horten an die ÖVP.</p><ul><li><strong>Jahr 2018:</strong> 588.000 Euro</li><li><strong>Jahr 2019 (bis Juni):</strong> 343.000 Euro</li></ul><h3 id="_2-die-methode-stuckelung-auf-49-000-euro" tabindex="-1">2. Die Methode: Stückelung auf 49.000 Euro <a class="header-anchor" href="#_2-die-methode-stuckelung-auf-49-000-euro" aria-label="Permalink to &quot;2. Die Methode: Stückelung auf 49.000 Euro&quot;">​</a></h3><p>Das Besondere an diesen Spenden war nicht nur die Höhe, sondern die Art der Überweisung. Die Summen wurden konsequent in Tranchen von jeweils <strong>49.000 Euro</strong> aufgeteilt.</p><ul><li><strong>Der Grund:</strong> Nach der damals geltenden Rechtslage mussten Spenden erst ab einem Einzelbetrag von <strong>50.000 Euro</strong> sofort dem Rechnungshof gemeldet und von diesem veröffentlicht werden.</li><li><strong>Der Effekt:</strong> Durch die Wahl von 49.000 Euro blieben die Spenden bis zur jährlichen Rechenschaftslegung (die erst mit großer Verzögerung erfolgt) der Öffentlichkeit verborgen. Die ÖVP musste diese Spenden erst im August 2019 – unter dem massiven Druck der Ibiza-Affäre – vorzeitig offenlegen.</li></ul><hr><h2 id="politische-und-rechtliche-konsequenzen" tabindex="-1">Politische und rechtliche Konsequenzen <a class="header-anchor" href="#politische-und-rechtliche-konsequenzen" aria-label="Permalink to &quot;Politische und rechtliche Konsequenzen&quot;">​</a></h2><p>Die „Causa Horten“ war der Hauptauslöser für eine historische Reform des österreichischen Parteiengesetzes im Juli 2019 (das sogenannte „Anti-Korruptions-Paket“).</p><h3 id="die-wichtigsten-anderungen" tabindex="-1">Die wichtigsten Änderungen: <a class="header-anchor" href="#die-wichtigsten-anderungen" aria-label="Permalink to &quot;Die wichtigsten Änderungen:&quot;">​</a></h3><ul><li><strong>Sofortige Meldepflicht:</strong> Spenden müssen nun bereits ab einem Betrag von <strong>2.500 Euro</strong> sofort gemeldet werden.</li><li><strong>Spenden-Obergrenze:</strong> Ein einzelner Spender darf pro Jahr insgesamt nur noch maximal <strong>7.500 Euro</strong> an eine Partei spenden. Ein Betrag von 931.000 Euro wäre heute also völlig illegal.</li><li><strong>Prüfkompetenz:</strong> Der Rechnungshof erhielt wesentlich stärkere Durchgriffsrechte, um die Finanzen der Parteien direkt zu prüfen.</li></ul><hr><h2 id="bedeutung-fur-das-„horten-mysterium" tabindex="-1">Bedeutung für das „Horten-Mysterium“ <a class="header-anchor" href="#bedeutung-fur-das-„horten-mysterium" aria-label="Permalink to &quot;Bedeutung für das „Horten-Mysterium“&quot;">​</a></h2><p>In unserem Film dient die Spendenliste als Brücke zwischen der historischen „Marktbereinigung“ Helmut Hortens und der modernen „Politikgestaltung“ seiner Witwe.</p><ul><li><strong>Satirisches Motiv:</strong> Wir zeigen die 49.000-Euro-Überweisungen als „künstlerische Punkte“ (Pointillismus), die erst aus der Entfernung das wahre Bild der politischen Einflussnahme ergeben.</li><li><strong>Die Moral:</strong> Während Helmut Horten in den 1930ern mit dem Segen des Staates Vermögen anhäufte, sorgte Heidi Horten mit ihrem Vermögen dafür, dass der Segen des Staates (in Form von politischem Wohlwollen) erhalten blieb.</li></ul><hr><p><em>Quellen: Berichte des Rechnungshofs (2019), Analysen von kurier.at, kontrast.at und profil.at zur Parteienfinanzierung.</em></p>',23)])])}const m=n(s,[["render",a]]);export{g as __pageData,m as default};
